# Instrucción 2/2011 simplificada: ¿va a la fiscalía de criminalidad
# informática y en qué categoría? (la lista del tema no es cerrada)
CATEGORIAS = {
    1: ("el objeto son los sistemas o las TIC",
        {"daños", "acceso sin autorización", "revelación de secretos"}),
    2: ("se sirve de las ventajas de las TIC",
        {"estafa", "pornografía infantil", "propiedad intelectual"}),
    3: ("TIC y especial complejidad",
        {"amenazas", "falsificación documental", "incitación al odio"}),
}

def fiscalia(delito, tic_determinante, especial_complejidad):
    if not (tic_determinante or especial_complejidad):
        return "no va a la especializada: la TIC no es determinante"
    for num, (nombre, delitos) in CATEGORIAS.items():
        if delito in delitos:
            return f"especializada, categoría {num} ({nombre})"
    return "especializada, categoría 3 (cláusula abierta)"

casos = [
    ("Tumban la web de un hospital", "daños", True, True),
    ("Phishing masivo a clientes", "estafa", True, False),
    ("Amenaza por WhatsApp a un vecino", "amenazas", False, False),
    ("Amenazas desde cuentas anónimas en TOR", "amenazas", True, True),
]
for texto, delito, det, comp in casos:
    print(f"{texto}\n  -> {fiscalia(delito, det, comp)}")
